<?php require_once("../Model/DatabaseConnection.php"); $db=new DatabaseConnection(); $connection=$db->openConnection(); $cart=$connection->query("SELECT * FROM cart ORDER BY id DESC"); require("header.php"); ?>Cart</div><?php require("footer.php"); ?><div class="tablebox"><div class="toolbar"><h2>Cart</h2><a class="btn danger" href="../Controller/cartController.php?action=clear">Clear Cart</a></div><table class="table"><tr><th>ID</th><th>Product</th><th>Quantity</th><th>Added At</th><th>Action</th></tr><?php while($c=$cart->fetch_assoc()): ?><tr><td><?=$c['id']?></td><td><?=htmlspecialchars($c['product_name'])?></td><td><?=$c['quantity']?></td><td><?=$c['added_at']?></td><td><a class="btn danger" href="../Controller/cartController.php?action=delete&id=<?=$c['id']?>">Remove</a></td></tr><?php endwhile; ?></table></div></main></div></body></html>
